from __future__ import annotations

from idp_core import IdentityPlaneError, SsoPerson, ZoomUserBinding


class IdentityStore:
    """Tenant-local materialized views used by attribution jobs."""

    def __init__(self, tenant: str = "default") -> None:
        self.tenant = str(tenant).strip() or "default"
        self.people: dict[str, SsoPerson] = {}
        self.bindings_by_zoom: dict[str, ZoomUserBinding] = {}

    def put_person(self, person: SsoPerson) -> None:
        self.people[person.subject] = person

    def put_binding(self, binding: ZoomUserBinding) -> None:
        self.bindings_by_zoom[binding.zoom_user_id] = binding

    def require_person(self, subject: str) -> SsoPerson:
        sid = str(subject).strip()
        if sid not in self.people:
            raise IdentityPlaneError("unknown subject")
        return self.people[sid]

    def require_binding(self, zoom_user_id: str) -> ZoomUserBinding:
        zid = str(zoom_user_id).strip()
        if zid not in self.bindings_by_zoom:
            raise IdentityPlaneError("unknown zoom_user_id")
        return self.bindings_by_zoom[zid]

    def bindings_for_subject(self, subject: str) -> list[ZoomUserBinding]:
        sid = str(subject).strip()
        return [b for b in self.bindings_by_zoom.values() if b.subject == sid]

    def person_count(self) -> int:
        return len(self.people)

    def binding_count(self) -> int:
        return len(self.bindings_by_zoom)

    def has_binding_for(self, zoom_user_id: str) -> bool:
        return str(zoom_user_id).strip() in self.bindings_by_zoom

    def describe_store(self) -> str:
        return f"t={self.tenant} p={self.person_count()} b={self.binding_count()}"

    def export_binding_ids(self) -> list[str]:
        return sorted(self.bindings_by_zoom.keys())

    def export_subjects(self) -> list[str]:
        return sorted(self.people.keys())

    def reset_for_tests(self) -> None:
        self.people.clear()
        self.bindings_by_zoom.clear()


def new_identity_store(tenant: str = "acme") -> IdentityStore:
    return IdentityStore(tenant)


def store_health_line(store: IdentityStore) -> str:
    return store.describe_store()


def assert_store_non_empty(store: IdentityStore) -> None:
    if store.person_count() == 0:
        raise IdentityPlaneError("store missing people")


def clone_binding_count(store: IdentityStore) -> int:
    return store.binding_count()


def bind_zoom_to_person(store: IdentityStore, zoom_user_id: str, subject: str, email: str) -> ZoomUserBinding:
    b = ZoomUserBinding(zoom_user_id, subject, email)
    store.put_binding(b)
    return b


def ensure_person_exists(store: IdentityStore, subject: str, email: str) -> SsoPerson:
    if subject in store.people:
        return store.people[subject]
    p = SsoPerson(subject, email)
    store.put_person(p)
    return p


def tenant_scope_label(store: IdentityStore) -> str:
    return f"tenant::{store.tenant}"


def binding_subjects_snapshot(store: IdentityStore) -> set[str]:
    return {b.subject for b in store.bindings_by_zoom.values()}


def store_pair_collision(store_a: IdentityStore, store_b: IdentityStore) -> bool:
    return store_a.tenant == store_b.tenant


def catalog_engine_stamp() -> str:
    return "binding-catalog-v2"


def list_zoom_ids_for_subject(store: IdentityStore, subject: str) -> list[str]:
    return sorted(b.zoom_user_id for b in store.bindings_for_subject(subject))


def materialization_revision() -> int:
    return 7

