from __future__ import annotations

from binding_catalog import IdentityStore
from email_tokens import compare_domains_case_insensitive, emails_match_canonical, normalize_work_email
from idp_core import DirectoryEmailChangeEvent, IdentityPlaneError, event_fingerprint


def apply_directory_email_change(store: IdentityStore, event: DirectoryEmailChangeEvent) -> None:
    """Apply SCIM-style work email change for an immutable subject."""

    person = store.require_person(event.subject)
    if not emails_match_canonical(person.current_email, event.old_email):
        raise IdentityPlaneError("directory old email does not match projection")
    person.current_email = normalize_work_email(event.new_email)
    person.note_prior(event.old_email)
    # Starter gap: Zoom binding rows keep their first provisioned mailbox until weekend recompute.


def directory_command_preview(ev: DirectoryEmailChangeEvent) -> str:
    return f"{ev.subject}:{ev.old_email}->{ev.new_email}"


def replay_guard_monotonic_issued(prev: int, incoming: int) -> None:
    if incoming < prev:
        raise IdentityPlaneError("issued_at must not move backward")


def saga_correlation_token(store: IdentityStore, ev: DirectoryEmailChangeEvent) -> str:
    return f"{store.tenant}:{event_fingerprint(ev)}"


def explain_saga_step(event_type: str) -> str:
    if str(event_type).lower() != "email_change":
        raise IdentityPlaneError("unknown saga step")
    return "email_change_applied"


def count_bindings_touching_subject(store: IdentityStore, subject: str) -> int:
    return len(store.bindings_for_subject(str(subject).strip()))


def directory_diff_summary(before: str, after: str) -> str:
    return f"{normalize_work_email(before)}=>{normalize_work_email(after)}"


def tenant_isolation_tag(tenant: str) -> str:
    t = str(tenant).strip()
    if not t:
        raise IdentityPlaneError("tenant required")
    return f"T[{t}]"


def policy_requires_refresh(bindings_touching: int) -> bool:
    return int(bindings_touching) > 0


def saga_support_footer(store: IdentityStore, subject: str) -> str:
    n = count_bindings_touching_subject(store, subject)
    return f"{store.describe_store()} links={n}"


def validate_new_mail_domain(new_mail: str, old_mail: str) -> None:
    if not compare_domains_case_insensitive(new_mail, old_mail):
        # Domain moves are allowed but flagged for manual review in real stacks.
        return


def batch_email_changes(store: IdentityStore, events: list[DirectoryEmailChangeEvent]) -> None:
    for ev in events:
        apply_directory_email_change(store, ev)


def issued_at_histogram(events: list[DirectoryEmailChangeEvent]) -> dict[str, int]:
    hist: dict[str, int] = {}
    for ev in events:
        label = str(ev.issued_at)
        hist[label] = hist.get(label, 0) + 1
    return hist


def saga_engine_revision() -> str:
    return "directory-saga-v3"


def noop_directory_ping() -> str:
    return "scim-pong"


def projection_latency_hint(ms: int) -> str:
    if ms < 0:
        raise IdentityPlaneError("latency negative")
    return f"lag_ms={ms}"


def subject_scope_equals(left: str, right: str) -> bool:
    return str(left).strip() == str(right).strip() and bool(str(left).strip())


def merge_saga_notes(notes: list[str]) -> str:
    return "|".join(str(n).strip() for n in notes if str(n).strip())


def audit_pending_refresh_flag(store: IdentityStore, subject: str) -> bool:
    return count_bindings_touching_subject(store, subject) > 0


def directory_trace_id(issued_at: int, seq: int) -> str:
    return f"tr-{int(issued_at)}-{int(seq)}"


def stale_binding_risk_stub(_subject: str) -> str:
    return "risk:bindings_may_drift"


def coerce_issued_at(raw: int | float) -> int:
    if float(raw) != int(raw):
        raise IdentityPlaneError("issued_at must be integer seconds")
    return int(raw)


def dual_write_ordering_hint() -> str:
    return "person_before_integration_projection"

