from __future__ import annotations

from idp_core import IdentityPlaneError


def normalize_work_email(raw: str) -> str:
    token = str(raw).strip().lower()
    if not token:
        raise IdentityPlaneError("email required")
    if "@" not in token:
        raise IdentityPlaneError("email must contain @")
    local, _, domain = token.partition("@")
    if not local or not domain:
        raise IdentityPlaneError("email malformed")
    return f"{local}@{domain}"


def emails_match_canonical(left: str, right: str) -> bool:
    return normalize_work_email(left) == normalize_work_email(right)


def mask_email_for_display(mail: str) -> str:
    norm = normalize_work_email(mail)
    local, _, domain = norm.partition("@")
    if len(local) <= 2:
        return f"*@{domain}"
    return f"{local[0]}*{local[-1]}@{domain}"


def domain_tail(mail: str) -> str:
    norm = normalize_work_email(mail)
    return norm.split("@", 1)[1]


def local_part(mail: str) -> str:
    norm = normalize_work_email(mail)
    return norm.split("@", 1)[0]


def batch_normalize(recipients: list[str]) -> list[str]:
    return [normalize_work_email(x) for x in recipients]


def compare_domains_case_insensitive(a: str, b: str) -> bool:
    return domain_tail(a).lower() == domain_tail(b).lower()


def strip_plus_tag(mail: str) -> str:
    norm = normalize_work_email(mail)
    local, _, domain = norm.partition("@")
    base = local.split("+", 1)[0]
    return f"{base}@{domain}"


def email_token_fingerprint(mail: str) -> str:
    n = normalize_work_email(mail)
    return str(hash(n) % 1_000_000)


def is_corporate_domain(mail: str, allowed: set[str]) -> bool:
    dom = domain_tail(mail).lower()
    return dom in {x.lower() for x in allowed}


def merge_recipient_lines(lines: list[str]) -> str:
    return ";".join(normalize_work_email(x) for x in lines)


def format_smtp_message_id(email: str, seq: int) -> str:
    return f"<{seq}.{normalize_work_email(email)}>"


def guard_ascii_mailbox(mail: str) -> None:
    norm = normalize_work_email(mail)
    if not norm.isascii():
        raise IdentityPlaneError("mailbox must be ascii in this kata")


def token_policy_version() -> str:
    return "email-token-v1"


def split_alias_path(mail: str) -> tuple[str, str]:
    norm = normalize_work_email(mail)
    local, _, domain = norm.partition("@")
    return local, domain


def explain_normalization_step(raw: str) -> str:
    return f"norm->{normalize_work_email(raw)}"


def downcase_list(values: list[str]) -> list[str]:
    return [str(v).strip().lower() for v in values if str(v).strip()]


def redact_repeatable_token(tok: str) -> str:
    t = str(tok).strip().lower()
    if len(t) < 4:
        return "***"
    return t[0] + "***" + t[-1]

