from __future__ import annotations

from binding_catalog import IdentityStore
from email_tokens import emails_match_canonical, normalize_work_email
from idp_core import IdentityPlaneError


def summarize_identity_plane(store: IdentityStore) -> dict[str, object]:
    mismatches = 0
    for binding in store.bindings_by_zoom.values():
        person = store.require_person(binding.subject)
        if not emails_match_canonical(binding.provisioned_email, person.current_email):
            mismatches += 1
    return {
        "tenant": store.tenant,
        "people": store.person_count(),
        "bindings": store.binding_count(),
        "mismatched_bindings": mismatches,
        "aligned": mismatches == 0,
    }


def audit_headline(summary: dict[str, object]) -> str:
    return f"{summary['tenant']} p={summary['people']} b={summary['bindings']}"


def alignment_required(summary: dict[str, object]) -> bool:
    return bool(summary.get("aligned"))


def export_mismatch_count(summary: dict[str, object]) -> int:
    return int(summary["mismatched_bindings"])


def support_bundle_from_summary(summary: dict[str, object]) -> str:
    return f"mis:{summary['mismatched_bindings']}|bind:{summary['bindings']}"


def dual_summary_equals(left: dict[str, object], right: dict[str, object]) -> bool:
    keys = ("people", "bindings", "mismatched_bindings")
    return all(left.get(k) == right.get(k) for k in keys)


def telemetry_digest(summary: dict[str, object]) -> str:
    return f"{summary['tenant']}:{summary['people']}:{summary['bindings']}"


def incident_from_mismatch(summary: dict[str, object]) -> str | None:
    if int(summary["mismatched_bindings"]) > 0:
        return "binding_directory_drift"
    return None


def audit_revision_tag() -> str:
    return "identity-audit-v2"


def rollup_subjects_touched(store: IdentityStore) -> int:
    subs = {b.subject for b in store.bindings_by_zoom.values()}
    return len(subs)


def explain_audit_zero_state(store: IdentityStore) -> str:
    if store.person_count() == 0:
        return "empty_store"
    return "populated"


def format_escalation_stub(summary: dict[str, object]) -> str:
    flag = incident_from_mismatch(summary)
    return flag or "ok"


def person_email_refresh_hint(subject: str, mail: str) -> str:
    return f"{subject.strip()}={normalize_work_email(mail)}"


def noop_audit_ping() -> str:
    return "audit-pong"


def compare_binding_person_emails(binding_mail: str, person_mail: str) -> bool:
    return emails_match_canonical(binding_mail, person_mail)


def audit_guard_non_negative(summary: dict[str, object]) -> None:
    if int(summary["mismatched_bindings"]) < 0:
        raise IdentityPlaneError("negative mismatch")

