from __future__ import annotations

from idp_core import IdentityPlaneError


SCIM_CONTENT_TYPES = ("application/scim+json", "application/json")
SCIM_SUPPORTED_VERSIONS = ("v2",)


def scim_schema_urn_user() -> str:
    return "urn:ietf:params:scim:schemas:core:2.0:User"


def scim_patch_op_supported(op: str) -> bool:
    o = str(op).strip().lower()
    return o in {"replace", "add", "remove"}


def require_scim_payload_size(byte_len: int) -> None:
    if byte_len < 1:
        raise IdentityPlaneError("payload empty")
    if byte_len > 1_000_000:
        raise IdentityPlaneError("payload too large for kata")


def scim_correlation_header(request_id: str) -> str:
    rid = str(request_id).strip()
    if not rid:
        raise IdentityPlaneError("request_id required")
    return f"scim-req:{rid}"


def scim_resource_name(resource_type: str) -> str:
    r = str(resource_type).strip().lower()
    if r != "user":
        raise IdentityPlaneError("only user resource supported here")
    return r


def scim_meta_location_stub(base_url: str, subject: str) -> str:
    b = str(base_url).rstrip("/")
    s = str(subject).strip()
    return f"{b}/Users/{s}"


def scim_change_log_line(op: str, path: str) -> str:
    return f"{str(op).lower()}:{str(path).strip()}"


def scim_batch_page_size() -> int:
    return 100


def scim_throttle_tokens_per_sec() -> int:
    return 25


def scim_version_header() -> str:
    return "SCIM-Version: 2.0"


def scim_filter_limit_chars() -> int:
    return 2_000


def explain_scim_contract(contract_id: str) -> str:
    cid = str(contract_id).strip()
    if not cid:
        raise IdentityPlaneError("contract_id required")
    return f"contract:{cid}"


def scim_error_reason(code: str) -> str:
    c = str(code).strip()
    return f"scim_err:{c}"


def scim_engine_stamp() -> str:
    return "scim-contracts-v1"


def noop_scim_ping() -> str:
    return "scim-pong"


def merge_scim_headers(headers: dict[str, str]) -> str:
    items = sorted(f"{k.lower()}={v}" for k, v in headers.items())
    return ";".join(items)


def scim_assert_content_type(ct: str) -> None:
    token = str(ct).split(";", 1)[0].strip().lower()
    if token not in ("application/scim+json", "application/json"):
        raise IdentityPlaneError("unexpected content type")


def scim_tenant_scope(tenant: str) -> str:
    return f"scim@{str(tenant).strip().lower()}"


def scim_etag_stub(subject: str, rev: int) -> str:
    return f'W/"{subject.strip()}:{rev}"'


def scim_max_parallel_links() -> int:
    return 4

